/**
 * Core game loop — scene, composer, subsystems.
 */

import { Color, PerspectiveCamera, Scene } from 'three';
import { CONFIG } from './config';
import type { AudioAPI, GameContext, RaceMode, RacePhase, Racer, Subsystem } from './types';
import type { Track } from '../race/track';
import { AdaptiveResolution, createRenderer } from '../render/renderer';
import { InkComposer } from '../render/composer';
import { createSky } from '../render/sky';
import { SHARED } from '../render/celMaterial';
import { SUN_DIR } from './palette';
import { createRaceFloor } from '../world/raceFloor';
import { createNeonSurround } from '../world/neonSurround';
import { createMountainTerrain } from '../world/mountainTerrain';
import type { ShipClassId } from '../race/raceSettings';
import { setShipClass } from '../race/raceSettings';

export class Game {
  readonly scene = new Scene();
  readonly camera: PerspectiveCamera;
  readonly renderer;
  readonly composer: InkComposer;
  readonly adaptive: AdaptiveResolution;
  readonly ctx: GameContext;

  private systems: Subsystem[] = [];
  private running = false;
  private last = 0;
  private raf = 0;
  private onFrame: ((ctx: GameContext) => void) | null = null;

  constructor(
    canvas: HTMLCanvasElement,
    track: Track,
    racers: Racer[],
    opts?: {
      combat?: boolean;
      audio?: AudioAPI | null;
      raceMode?: RaceMode;
      laps?: number;
      shipClass?: ShipClassId;
    },
  ) {
    const { renderer } = createRenderer(canvas);
    this.renderer = renderer;
    this.camera = new PerspectiveCamera(
      CONFIG.render.fov,
      1,
      CONFIG.render.near,
      CONFIG.render.far,
    );
    this.camera.position.set(0, 60, -40);
    this.adaptive = new AdaptiveResolution(renderer);
    this.composer = new InkComposer(renderer, this.scene, this.camera);

    this.scene.background = new Color(0x16161f);
    this.scene.add(createSky());
    this.scene.add(createMountainTerrain(track));
    this.scene.add(createNeonSurround(track));
    this.scene.add(createRaceFloor(track));
    this.scene.add(track.group);

    const shipClass = opts?.shipClass ?? 'standard';
    setShipClass(shipClass);

    const player = racers.find((r) => r.isPlayer) ?? racers[0];
    this.ctx = {
      scene: this.scene,
      camera: this.camera,
      renderer,
      time: 0,
      dt: 0,
      frame: 0,
      racers,
      player,
      track,
      phase: 'countdown' as RacePhase,
      raceTime: 0,
      raceMode: opts?.raceMode ?? (opts?.combat ? 'race' : 'timeattack'),
      laps: opts?.laps ?? CONFIG.race.laps,
      shipClass,
      combat: !!opts?.combat,
      audio: opts?.audio ?? null,
      cameraRig: null,
    };

    for (const r of racers) this.scene.add(r.root);
  }

  add(sys: Subsystem) {
    this.systems.push(sys);
    this.systems.sort((a, b) => a.order - b.order);
    sys.init?.(this.ctx);
    // ChaseCamera implements CameraRig — expose for shake / cinematic / HUD.
    if ('addShake' in sys && 'setMode' in sys) {
      this.ctx.cameraRig = sys as unknown as import('./types').CameraRig;
    }
  }

  setFrameHook(fn: (ctx: GameContext) => void) {
    this.onFrame = fn;
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    const loop = (now: number) => {
      if (!this.running) return;
      this.raf = requestAnimationFrame(loop);
      let dt = (now - this.last) / 1000;
      this.last = now;
      if (dt > 0.05) dt = 0.05;
      this.tick(dt);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  private tick(dt: number) {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const pr = this.adaptive.pixelRatio;
    this.renderer.setPixelRatio(pr);
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / Math.max(1, h);
    this.camera.updateProjectionMatrix();
    this.composer.setSize(w, h, pr);

    this.ctx.dt = dt;
    this.ctx.time += dt;
    this.ctx.frame += 1;

    SHARED.uTime.value = this.ctx.time;
    SHARED.uSunDir.value.set(SUN_DIR.x, SUN_DIR.y, SUN_DIR.z);
    SHARED.uResolution.value.set(w * pr, h * pr);
    SHARED.uCameraPos.value.copy(this.camera.position);

    for (const sys of this.systems) sys.update(this.ctx);

    const t0 = performance.now();
    this.composer.render();
    const frameMs = performance.now() - t0;
    this.adaptive.update(frameMs, dt);

    this.onFrame?.(this.ctx);
  }

  dispose() {
    this.stop();
    for (const sys of this.systems) sys.dispose?.();
    this.composer.dispose();
    this.renderer.dispose();
  }
}
