/**
 * Cel-shaded rocket proximity bursts — hit / dud / fuse flashes.
 */

import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Group,
  Mesh,
} from 'three';
import { HEX } from '../core/palette';
import { applyCel, createCelMaterial, nextObjectId, type CelMaterialSet } from '../render/celMaterial';

const POOL = 12;
const SHARDS = 10;

export type RocketImpactKind = 'hit' | 'dud' | 'fuse';

type Shard = {
  mesh: Mesh;
  vx: number;
  vy: number;
  vz: number;
  spinX: number;
  spinY: number;
  spinZ: number;
  base: number;
};

type Burst = {
  alive: boolean;
  age: number;
  life: number;
  kind: RocketImpactKind;
  root: Group;
  core: Mesh;
  ringA: Mesh;
  ringB: Mesh;
  shards: Shard[];
};

function facetNormals(positions: Float32Array): Float32Array {
  const normals = new Float32Array(positions.length);
  for (let i = 0; i < positions.length; i += 9) {
    const ax = positions[i + 3]! - positions[i]!;
    const ay = positions[i + 4]! - positions[i + 1]!;
    const az = positions[i + 5]! - positions[i + 2]!;
    const bx = positions[i + 6]! - positions[i]!;
    const by = positions[i + 7]! - positions[i + 1]!;
    const bz = positions[i + 8]! - positions[i + 2]!;
    let nx = ay * bz - az * by;
    let ny = az * bx - ax * bz;
    let nz = ax * by - ay * bx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len;
    ny /= len;
    nz /= len;
    for (let k = 0; k < 3; k++) {
      normals[i + k * 3] = nx;
      normals[i + k * 3 + 1] = ny;
      normals[i + k * 3 + 2] = nz;
    }
  }
  return normals;
}

function geoFrom(pos: number[]): BufferGeometry {
  const arr = new Float32Array(pos);
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(arr, 3));
  g.setAttribute('normal', new BufferAttribute(facetNormals(arr), 3));
  g.computeBoundingSphere();
  return g;
}

function spikeGeo(): BufferGeometry {
  const s = 0.42;
  return geoFrom([
    0, s, 0, -s * 0.7, -s * 0.3, s * 0.5, s * 0.7, -s * 0.3, s * 0.5,
    0, s, 0, s * 0.7, -s * 0.3, s * 0.5, 0, -s * 0.15, -s,
    0, s, 0, 0, -s * 0.15, -s, -s * 0.7, -s * 0.3, s * 0.5,
    -s * 0.7, -s * 0.3, s * 0.5, 0, -s * 0.15, -s, s * 0.7, -s * 0.3, s * 0.5,
  ]);
}

function coreGeo(): BufferGeometry {
  const r = 0.85;
  const y = r * 0.75;
  return geoFrom([
    0, y, 0, r, 0, 0, 0, 0, r,
    0, y, 0, 0, 0, r, -r, 0, 0,
    0, y, 0, -r, 0, 0, 0, 0, -r,
    0, y, 0, 0, 0, -r, r, 0, 0,
    0, -y, 0, 0, 0, r, r, 0, 0,
    0, -y, 0, -r, 0, 0, 0, 0, r,
    0, -y, 0, 0, 0, -r, -r, 0, 0,
    0, -y, 0, r, 0, 0, 0, 0, -r,
  ]);
}

function ringGeo(r0: number, r1: number, y: number, N = 12): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  for (let i = 0; i < N; i++) {
    const a0 = (i / N) * Math.PI * 2;
    const a1 = ((i + 1) / N) * Math.PI * 2;
    const v = [
      [Math.cos(a0) * r0, y, Math.sin(a0) * r0],
      [Math.cos(a1) * r0, y, Math.sin(a1) * r0],
      [Math.cos(a1) * r1, y, Math.sin(a1) * r1],
      [Math.cos(a0) * r1, y, Math.sin(a0) * r1],
    ] as const;
    for (const tri of [
      [v[0], v[1], v[2]],
      [v[0], v[2], v[3]],
    ]) {
      for (const p of tri) {
        pos.push(p[0], p[1], p[2]);
        nor.push(0, 1, 0);
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  return g;
}

function mat(hex: number, name: string): CelMaterialSet {
  const color = new Color(hex);
  return createCelMaterial({
    name,
    color,
    rampColors: [
      color.clone().multiplyScalar(0.65).lerp(new Color(HEX.boost), 0.25),
      color.clone().multiplyScalar(1.05),
      color.clone().lerp(new Color(HEX.boostHot), 0.4),
      new Color(HEX.sunCore),
    ],
    flatShading: true,
    rimColor: new Color(HEX.foam),
    rimPower: 1.3,
    rimStrength: 1.25,
    outlineWidthPx: 2.4,
    flareMask: 1,
    ambientStrength: 1.45,
    specStrength: 0.55,
  });
}

/**
 * Lightweight pool of cel impact pops. Owned by RocketField (not a Subsystem).
 */
export class RocketImpactField {
  private root = new Group();
  private pool: Burst[] = [];
  private spike = spikeGeo();
  private core = coreGeo();
  private ringA = ringGeo(0.9, 1.2, 0.04);
  private ringB = ringGeo(1.4, 1.75, 0.07);
  private matHit = mat(HEX.boostHot, 'rktImpactHit');
  private matRing = mat(HEX.boost, 'rktImpactRing');
  private matDud = mat(HEX.warn, 'rktImpactDud');
  private ready = false;

  init(scene: { add: (o: Group) => void }) {
    this.root.name = 'rocketImpacts';
    scene.add(this.root);
    for (let i = 0; i < POOL; i++) this.pool.push(this.makeBurst());
    this.ready = true;
  }

  private makeBurst(): Burst {
    const root = new Group();
    root.visible = false;

    const core = new Mesh(this.core);
    core.userData.objectId = nextObjectId();
    applyCel(core, this.matHit);
    root.add(core);

    const ringA = new Mesh(this.ringA);
    ringA.userData.objectId = nextObjectId();
    applyCel(ringA, this.matRing);
    root.add(ringA);

    const ringB = new Mesh(this.ringB);
    ringB.userData.objectId = nextObjectId();
    applyCel(ringB, this.matDud);
    root.add(ringB);

    const shards: Shard[] = [];
    for (let i = 0; i < SHARDS; i++) {
      const mesh = new Mesh(this.spike);
      mesh.userData.objectId = nextObjectId();
      applyCel(mesh, i % 2 === 0 ? this.matHit : this.matRing);
      mesh.visible = false;
      root.add(mesh);
      shards.push({
        mesh,
        vx: 0,
        vy: 0,
        vz: 0,
        spinX: 0,
        spinY: 0,
        spinZ: 0,
        base: 1,
      });
    }

    this.root.add(root);
    return {
      alive: false,
      age: 0,
      life: 0.75,
      kind: 'hit',
      root,
      core,
      ringA,
      ringB,
      shards,
    };
  }

  private alloc(): Burst {
    for (const b of this.pool) if (!b.alive) return b;
    let oldest = this.pool[0]!;
    for (const b of this.pool) if (b.age > oldest.age) oldest = b;
    oldest.alive = false;
    oldest.root.visible = false;
    return oldest;
  }

  spawn(x: number, y: number, z: number, kind: RocketImpactKind = 'hit') {
    if (!this.ready) return;
    const b = this.alloc();
    const big = kind === 'hit';
    const life = kind === 'fuse' ? 0.45 : kind === 'dud' ? 0.55 : 0.85;

    b.alive = true;
    b.age = 0;
    b.life = life;
    b.kind = kind;
    b.root.visible = true;
    b.root.position.set(x, y + 0.4, z);

    applyCel(b.core, big ? this.matHit : this.matDud);
    applyCel(b.ringA, big ? this.matRing : this.matDud);
    applyCel(b.ringB, big ? this.matHit : this.matRing);

    b.core.scale.setScalar(big ? 0.55 : 0.35);
    b.ringA.scale.setScalar(0.35);
    b.ringB.scale.setScalar(0.45);

    const n = big ? SHARDS : 6;
    for (let i = 0; i < SHARDS; i++) {
      const s = b.shards[i]!;
      if (i >= n) {
        s.mesh.visible = false;
        continue;
      }
      const yaw = Math.random() * Math.PI * 2;
      const pitch = (Math.random() - 0.2) * 1.35;
      const spd = (big ? 16 : 10) + Math.random() * (big ? 18 : 10);
      s.vx = Math.cos(yaw) * Math.cos(pitch) * spd;
      s.vy = Math.sin(pitch) * spd * 0.75 + 4 + Math.random() * 6;
      s.vz = Math.sin(yaw) * Math.cos(pitch) * spd;
      s.spinX = (Math.random() - 0.5) * 16;
      s.spinY = (Math.random() - 0.5) * 18;
      s.spinZ = (Math.random() - 0.5) * 16;
      s.base = (big ? 0.85 : 0.55) + Math.random() * 0.7;
      s.mesh.visible = true;
      s.mesh.position.set(
        (Math.random() - 0.5) * 0.6,
        (Math.random() - 0.5) * 0.5,
        (Math.random() - 0.5) * 0.6,
      );
      s.mesh.scale.setScalar(s.base);
      s.mesh.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
    }
  }

  update(dt: number) {
    if (!this.ready) return;
    for (const b of this.pool) {
      if (!b.alive) continue;
      b.age += dt;
      const t = b.age / b.life;
      if (t >= 1) {
        b.alive = false;
        b.root.visible = false;
        continue;
      }

      const punch = b.kind === 'hit' ? 1.15 : 0.75;
      const coreScale =
        t < 0.1
          ? 0.35 + (t / 0.1) * 1.8 * punch
          : Math.max(0.04, 2.1 * punch * (1 - (t - 0.1) / 0.9));
      b.core.scale.setScalar(coreScale);
      b.core.rotation.y += dt * 5;
      b.core.rotation.x += dt * 2.4;
      b.core.visible = t < 0.5;

      const ringT = Math.min(1, t / 0.75);
      b.ringA.scale.setScalar(0.4 + ringT * 5.5 * punch);
      b.ringB.scale.setScalar(0.55 + ringT * 7.5 * punch);
      b.ringA.rotation.y += dt * 2.2;
      b.ringB.rotation.y -= dt * 1.6;
      b.ringA.visible = t < 0.7;
      b.ringB.visible = t < 0.85;

      for (const s of b.shards) {
        if (!s.mesh.visible && t > 0) continue;
        s.vy -= 26 * dt;
        s.mesh.position.x += s.vx * dt;
        s.mesh.position.y += s.vy * dt;
        s.mesh.position.z += s.vz * dt;
        s.mesh.rotation.x += s.spinX * dt;
        s.mesh.rotation.y += s.spinY * dt;
        s.mesh.rotation.z += s.spinZ * dt;
        const fade = t > 0.5 ? 1 - (t - 0.5) / 0.5 : 1;
        s.mesh.scale.setScalar(s.base * Math.max(0.04, fade));
        s.mesh.visible = fade > 0.05;
      }
    }
  }

  clear() {
    for (const b of this.pool) {
      b.alive = false;
      b.root.visible = false;
    }
  }

  dispose() {
    this.root.removeFromParent();
    this.ready = false;
  }
}
