/**
 * Mobile / touch overlay — large left steer zone + few big right actions.
 */

const css = /* css */ `
#touch {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}
#touch .touch-safe {
  position: absolute;
  inset: 0;
  padding:
    max(6px, env(safe-area-inset-top))
    max(8px, env(safe-area-inset-right))
    max(8px, env(safe-area-inset-bottom))
    max(8px, env(safe-area-inset-left));
  pointer-events: none;
}
#touch .touch-steer-zone,
#touch .touch-btn {
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
}
/* Fat left drag area — grab anywhere here to steer. */
#touch .touch-steer-zone {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 48%;
  height: 62%;
}
#touch .touch-steer {
  position: absolute;
  left: max(12px, env(safe-area-inset-left));
  bottom: max(14px, env(safe-area-inset-bottom));
  width: min(34vw, 140px);
  height: min(34vw, 140px);
  border-radius: 50%;
  background: rgba(22, 22, 31, 0.28);
  border: 1.5px solid rgba(30, 240, 240, 0.42);
  pointer-events: none;
}
#touch .touch-steer-ring {
  position: absolute;
  inset: 20%;
  border-radius: 50%;
  border: 1px solid rgba(30, 240, 240, 0.18);
  pointer-events: none;
}
#touch .touch-steer-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 38%;
  height: 38%;
  border-radius: 50%;
  background: rgba(30, 240, 240, 0.55);
  border: 1.5px solid rgba(18, 8, 28, 0.7);
  transform: translate(-50%, -50%);
  pointer-events: none;
}
#touch .touch-steer.is-active {
  background: rgba(255, 61, 154, 0.28);
  border-color: rgba(30, 240, 240, 0.7);
}
#touch .touch-actions {
  position: absolute;
  right: max(8px, env(safe-area-inset-right));
  bottom: max(10px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(2, minmax(72px, 18vw));
  grid-template-areas:
    "boost fire"
    "brake nitro";
  gap: 10px;
  pointer-events: none;
}
#touch .touch-btn {
  pointer-events: auto;
  appearance: none;
  border: 2px solid rgba(255, 61, 154, 0.5);
  background: rgba(22, 22, 31, 0.4);
  color: rgba(242, 251, 255, 0.95);
  font: 800 12px/1 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.12em;
  border-radius: 14px;
  min-height: 58px;
  padding: 0 8px;
  text-transform: uppercase;
  opacity: 0.88;
}
#touch .touch-boost {
  grid-area: boost;
  min-height: 64px;
  border-color: rgba(255, 61, 139, 0.7);
  color: #ffb0d8;
}
#touch .touch-fire {
  grid-area: fire;
  min-height: 64px;
  border-color: rgba(255, 201, 60, 0.75);
  color: #ffe08a;
}
#touch .touch-brake {
  grid-area: brake;
  border-color: rgba(255, 90, 90, 0.7);
  color: #ffc2c2;
}
#touch .touch-nitro {
  grid-area: nitro;
  border-color: rgba(77, 255, 176, 0.7);
  color: #c4ffe6;
}
#touch .touch-btn.is-active {
  opacity: 1;
  box-shadow: 0 0 14px rgba(255, 61, 154, 0.3);
}
#touch .touch-brake.is-active {
  background: rgba(255, 90, 90, 0.45);
}
#touch .touch-fire.is-active {
  background: rgba(255, 201, 60, 0.4);
}
#touch .touch-nitro.is-active {
  background: rgba(77, 255, 176, 0.35);
}
#touch .touch-boost.is-active {
  background: rgba(255, 61, 139, 0.45);
}

@media (orientation: landscape) {
  #touch .touch-steer-zone {
    width: 44%;
    height: 70%;
  }
  #touch .touch-steer {
    width: min(26vw, 120px);
    height: min(26vw, 120px);
  }
  #touch .touch-actions {
    grid-template-columns: repeat(2, minmax(64px, 14vw));
    gap: 8px;
  }
  #touch .touch-btn { min-height: 50px; font-size: 11px; }
  #touch .touch-boost,
  #touch .touch-fire { min-height: 56px; }
}

@media (max-height: 420px) {
  #touch .touch-steer {
    width: min(22vw, 96px);
    height: min(22vw, 96px);
  }
  #touch .touch-btn { min-height: 42px; font-size: 10px; border-radius: 10px; }
  #touch .touch-boost,
  #touch .touch-fire { min-height: 46px; }
}
`;

let injected = false;
export function injectTouchStyles() {
  if (injected || typeof document === 'undefined') return;
  injected = true;
  const style = document.createElement('style');
  style.id = 'touch-controls-css';
  style.textContent = css;
  document.head.appendChild(style);
}
