/**
 * Cel-shaded ship wreck blast — shards + flash rings when hull hits 0.
 */

import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Group,
  Mesh,
} from 'three';
import { HEX, RACER_COLORS } from '../core/palette';
import type { GameContext, Racer, Subsystem } from '../core/types';
import { applyCel, createCelMaterial, nextObjectId, type CelMaterialSet } from '../render/celMaterial';

const LIFE = 1.35;
const SHARD_COUNT = 14;
const POOL = 8;

type Shard = {
  mesh: Mesh;
  vx: number;
  vy: number;
  vz: number;
  spinX: number;
  spinY: number;
  spinZ: number;
};

type Blast = {
  alive: boolean;
  age: number;
  life: number;
  root: Group;
  core: Mesh;
  ringA: Mesh;
  ringB: Mesh;
  shards: Shard[];
};

function facetNormals(positions: Float32Array): Float32Array {
  const normals = new Float32Array(positions.length);
  for (let i = 0; i < positions.length; i += 9) {
    const ax = positions[i + 3]! - positions[i]!;
    const ay = positions[i + 4]! - positions[i + 1]!;
    const az = positions[i + 5]! - positions[i + 2]!;
    const bx = positions[i + 6]! - positions[i]!;
    const by = positions[i + 7]! - positions[i + 1]!;
    const bz = positions[i + 8]! - positions[i + 2]!;
    let nx = ay * bz - az * by;
    let ny = az * bx - ax * bz;
    let nz = ax * by - ay * bx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len;
    ny /= len;
    nz /= len;
    for (let k = 0; k < 3; k++) {
      normals[i + k * 3] = nx;
      normals[i + k * 3 + 1] = ny;
      normals[i + k * 3 + 2] = nz;
    }
  }
  return normals;
}

function makeShardGeo(): BufferGeometry {
  // Jagged tetra — reads as hull shrapnel at chase distance.
  const s = 0.55;
  const pos = new Float32Array([
    0, s, 0, -s * 0.8, -s * 0.4, s * 0.6, s * 0.8, -s * 0.4, s * 0.6,
    0, s, 0, s * 0.8, -s * 0.4, s * 0.6, 0, -s * 0.2, -s,
    0, s, 0, 0, -s * 0.2, -s, -s * 0.8, -s * 0.4, s * 0.6,
    -s * 0.8, -s * 0.4, s * 0.6, 0, -s * 0.2, -s, s * 0.8, -s * 0.4, s * 0.6,
  ]);
  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(pos, 3));
  geo.setAttribute('normal', new BufferAttribute(facetNormals(pos), 3));
  return geo;
}

function makeCoreGeo(): BufferGeometry {
  // Low-poly burst kernel.
  const r = 1.1;
  const pos: number[] = [];
  const push = (ax: number, ay: number, az: number, bx: number, by: number, bz: number, cx: number, cy: number, cz: number) => {
    pos.push(ax, ay, az, bx, by, bz, cx, cy, cz);
  };
  const y = r * 0.85;
  push(0, y, 0, r, 0, 0, 0, 0, r);
  push(0, y, 0, 0, 0, r, -r, 0, 0);
  push(0, y, 0, -r, 0, 0, 0, 0, -r);
  push(0, y, 0, 0, 0, -r, r, 0, 0);
  push(0, -y, 0, 0, 0, r, r, 0, 0);
  push(0, -y, 0, -r, 0, 0, 0, 0, r);
  push(0, -y, 0, 0, 0, -r, -r, 0, 0);
  push(0, -y, 0, r, 0, 0, 0, 0, -r);
  const arr = new Float32Array(pos);
  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(arr, 3));
  geo.setAttribute('normal', new BufferAttribute(facetNormals(arr), 3));
  return geo;
}

function ringGeo(r0: number, r1: number, y: number, N = 14): BufferGeometry {
  const positions: number[] = [];
  const normals: number[] = [];
  for (let i = 0; i < N; i++) {
    const a0 = (i / N) * Math.PI * 2;
    const a1 = ((i + 1) / N) * Math.PI * 2;
    const verts = [
      [Math.cos(a0) * r0, y, Math.sin(a0) * r0],
      [Math.cos(a1) * r0, y, Math.sin(a1) * r0],
      [Math.cos(a1) * r1, y, Math.sin(a1) * r1],
      [Math.cos(a0) * r1, y, Math.sin(a0) * r1],
    ] as const;
    for (const tri of [
      [verts[0], verts[1], verts[2]],
      [verts[0], verts[2], verts[3]],
    ]) {
      for (const v of tri) {
        positions.push(v[0], v[1], v[2]);
        normals.push(0, 1, 0);
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
  return g;
}

function makeMat(hex: number, name: string, flare = 1): CelMaterialSet {
  const color = new Color(hex);
  return createCelMaterial({
    name,
    color,
    rampColors: [
      color.clone().multiplyScalar(0.7),
      color.clone().multiplyScalar(1.05),
      color.clone().multiplyScalar(1.45),
      color.clone().multiplyScalar(1.85),
    ],
    flatShading: true,
    rimColor: new Color(HEX.foam),
    rimPower: 1.4,
    rimStrength: 1,
    outlineWidthPx: 2.6,
    flareMask: flare,
  });
}

export class ShipExplosionFx implements Subsystem {
  readonly name = 'shipExplosion';
  /** After collisions so wrecks this frame still get a blast. */
  readonly order = 58;

  private root = new Group();
  private pool: Blast[] = [];
  private triggered = new Set<number>();
  private shardGeo = makeShardGeo();
  private coreGeo = makeCoreGeo();
  private ringGeoA = ringGeo(1.2, 1.55, 0.05);
  private ringGeoB = ringGeo(1.9, 2.35, 0.08);
  private matCore = makeMat(HEX.boostHot, 'wreckCore', 1);
  private matRing = makeMat(HEX.boost, 'wreckRing', 1);
  private matFire = makeMat(HEX.warn, 'wreckFire', 1);
  private liveryMats = new Map<number, CelMaterialSet>();
  private ready = false;

  init(ctx: GameContext) {
    this.root.name = 'shipExplosions';
    ctx.scene.add(this.root);
    for (let i = 0; i < POOL; i++) this.pool.push(this.makeBlast());
    this.ready = true;
  }

  private makeBlast(): Blast {
    const root = new Group();
    root.visible = false;

    const core = new Mesh(this.coreGeo);
    core.userData.objectId = nextObjectId();
    applyCel(core, this.matCore);
    root.add(core);

    const ringA = new Mesh(this.ringGeoA);
    ringA.userData.objectId = nextObjectId();
    applyCel(ringA, this.matRing);
    root.add(ringA);

    const ringB = new Mesh(this.ringGeoB);
    ringB.userData.objectId = nextObjectId();
    applyCel(ringB, this.matFire);
    root.add(ringB);

    const shards: Shard[] = [];
    for (let i = 0; i < SHARD_COUNT; i++) {
      const mesh = new Mesh(this.shardGeo);
      mesh.userData.objectId = nextObjectId();
      applyCel(mesh, i % 3 === 0 ? this.matFire : i % 3 === 1 ? this.matCore : this.matRing);
      mesh.visible = false;
      root.add(mesh);
      shards.push({ mesh, vx: 0, vy: 0, vz: 0, spinX: 0, spinY: 0, spinZ: 0 });
    }

    this.root.add(root);
    return {
      alive: false,
      age: 0,
      life: LIFE,
      root,
      core,
      ringA,
      ringB,
      shards,
    };
  }

  private alloc(): Blast | null {
    for (const b of this.pool) if (!b.alive) return b;
    // Steal oldest
    let oldest = this.pool[0]!;
    for (const b of this.pool) if (b.age > oldest.age) oldest = b;
    oldest.alive = false;
    oldest.root.visible = false;
    return oldest;
  }

  private spawn(r: Racer) {
    const blast = this.alloc();
    if (!blast) return;

    const p = r.state.position;
    const hullHex = RACER_COLORS[r.id % RACER_COLORS.length]?.hex ?? HEX.hull0;
    let livery = this.liveryMats.get(r.id);
    if (!livery) {
      livery = makeMat(hullHex, `wreckHull_${r.id}`, 0);
      this.liveryMats.set(r.id, livery);
    }
    for (let i = 0; i < 4; i++) {
      applyCel(blast.shards[i]!.mesh, livery);
    }

    blast.alive = true;
    blast.age = 0;
    blast.life = LIFE;
    blast.root.visible = true;
    blast.root.position.set(p.x, p.y + 0.6, p.z);

    blast.core.scale.setScalar(0.35);
    blast.ringA.scale.setScalar(0.4);
    blast.ringB.scale.setScalar(0.55);
    blast.ringA.rotation.set(0, 0, 0);
    blast.ringB.rotation.set(0.15, 0, 0.1);

    for (const s of blast.shards) {
      const yaw = Math.random() * Math.PI * 2;
      const pitch = (Math.random() - 0.25) * 1.2;
      const spd = 14 + Math.random() * 22;
      s.vx = Math.cos(yaw) * Math.cos(pitch) * spd;
      s.vy = Math.sin(pitch) * spd * 0.85 + 6 + Math.random() * 8;
      s.vz = Math.sin(yaw) * Math.cos(pitch) * spd;
      s.spinX = (Math.random() - 0.5) * 14;
      s.spinY = (Math.random() - 0.5) * 16;
      s.spinZ = (Math.random() - 0.5) * 14;
      s.mesh.visible = true;
      s.mesh.position.set(
        (Math.random() - 0.5) * 1.2,
        (Math.random() - 0.5) * 0.8,
        (Math.random() - 0.5) * 1.2,
      );
      const sc = 0.7 + Math.random() * 1.1;
      s.mesh.userData.baseScale = sc;
      s.mesh.scale.setScalar(sc);
      s.mesh.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
    }

    r.root.visible = false;
  }

  update(ctx: GameContext) {
    if (!this.ready) return;
    const dt = ctx.dt;

    // Race restart — restore craft and clear fuse.
    if (ctx.phase === 'countdown') {
      if (this.triggered.size > 0) {
        this.triggered.clear();
        for (const b of this.pool) {
          b.alive = false;
          b.root.visible = false;
        }
        for (const r of ctx.racers) r.root.visible = true;
      }
      return;
    }

    for (const r of ctx.racers) {
      if (!r.destroyed) {
        this.triggered.delete(r.id);
        continue;
      }
      if (this.triggered.has(r.id)) continue;
      this.triggered.add(r.id);
      this.spawn(r);
      ctx.audio?.playExplode();
      if (r.isPlayer) ctx.cameraRig?.addShake(0.85);
      else if (ctx.player && !ctx.player.destroyed) {
        const dx = r.state.position.x - ctx.player.state.position.x;
        const dz = r.state.position.z - ctx.player.state.position.z;
        const dist = Math.hypot(dx, dz);
        if (dist < 55) ctx.cameraRig?.addShake(0.25 * (1 - dist / 55));
      }
    }

    for (const b of this.pool) {
      if (!b.alive) continue;
      b.age += dt;
      const t = b.age / b.life;
      if (t >= 1) {
        b.alive = false;
        b.root.visible = false;
        continue;
      }

      // Flash kernel: punch out then collapse.
      const coreScale =
        t < 0.12 ? 0.4 + (t / 0.12) * 2.4 : Math.max(0.05, 2.8 * (1 - (t - 0.12) / 0.88));
      b.core.scale.setScalar(coreScale);
      b.core.rotation.y += dt * 4;
      b.core.rotation.x += dt * 2.2;
      b.core.visible = t < 0.55;

      // Shock rings expand + fade via scale squash.
      const ringT = Math.min(1, t / 0.85);
      b.ringA.scale.setScalar(0.5 + ringT * 6.5);
      b.ringB.scale.setScalar(0.7 + ringT * 9.5);
      b.ringA.rotation.y += dt * 1.8;
      b.ringB.rotation.y -= dt * 1.2;
      b.ringA.visible = t < 0.75;
      b.ringB.visible = t < 0.9;

      for (const s of b.shards) {
        s.vy -= 28 * dt;
        s.mesh.position.x += s.vx * dt;
        s.mesh.position.y += s.vy * dt;
        s.mesh.position.z += s.vz * dt;
        s.mesh.rotation.x += s.spinX * dt;
        s.mesh.rotation.y += s.spinY * dt;
        s.mesh.rotation.z += s.spinZ * dt;
        const fade = t > 0.55 ? 1 - (t - 0.55) / 0.45 : 1;
        const bs = (s.mesh.userData.baseScale as number) ?? 1;
        s.mesh.scale.setScalar(bs * Math.max(0.05, fade));
        s.mesh.visible = fade > 0.04;
      }
    }
  }

  dispose() {
    this.root.removeFromParent();
    this.ready = false;
  }
}
