/**
 * Random health boxes along the elevated circuit.
 * Collect to repair hull zones — tunables in `core/combatTune.ts`.
 */

import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Group,
  Mesh,
  Vector3,
} from 'three';
import { COMBAT } from '../core/combatTune';
import { HEX, PAL } from '../core/palette';
import { Rng } from '../core/rng';
import type { GameContext, Subsystem, TrackAPI } from '../core/types';
import { applyCel, createCelMaterial, nextObjectId } from '../render/celMaterial';
import { repairHull } from '../ship/hull';

type Slot = {
  alive: boolean;
  x: number;
  y: number;
  z: number;
  respawnAt: number;
  root: Group;
};

function boxGeo(sx: number, sy: number, sz: number): BufferGeometry {
  const hx = sx * 0.5;
  const hy = sy * 0.5;
  const hz = sz * 0.5;
  const faces: [number, number, number][][] = [
    [[-hx, hy, -hz], [hx, hy, -hz], [hx, hy, hz], [-hx, hy, hz]],
    [[-hx, -hy, hz], [hx, -hy, hz], [hx, -hy, -hz], [-hx, -hy, -hz]],
    [[-hx, -hy, hz], [-hx, hy, hz], [hx, hy, hz], [hx, -hy, hz]],
    [[hx, -hy, -hz], [hx, hy, -hz], [-hx, hy, -hz], [-hx, -hy, -hz]],
    [[hx, -hy, -hz], [hx, -hy, hz], [hx, hy, hz], [hx, hy, -hz]],
    [[-hx, -hy, hz], [-hx, -hy, -hz], [-hx, hy, -hz], [-hx, hy, hz]],
  ];
  const positions: number[] = [];
  const normals: number[] = [];
  for (const f of faces) {
    const ax = f[1]![0] - f[0]![0];
    const ay = f[1]![1] - f[0]![1];
    const az = f[1]![2] - f[0]![2];
    const bx = f[2]![0] - f[0]![0];
    const by = f[2]![1] - f[0]![1];
    const bz = f[2]![2] - f[0]![2];
    let nx = ay * bz - az * by;
    let ny = az * bx - ax * bz;
    let nz = ax * by - ay * bx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len;
    ny /= len;
    nz /= len;
    for (const tri of [
      [f[0], f[1], f[2]],
      [f[0], f[2], f[3]],
    ]) {
      for (const v of tri) {
        positions.push(v![0], v![1], v![2]);
        normals.push(nx, ny, nz);
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
  g.computeBoundingSphere();
  return g;
}

function plusGeo(): BufferGeometry {
  const t = 0.11;
  const a = 0.38;
  const y = 0.42;
  const quads: [number, number, number][][] = [
    [[-t, y, -a], [t, y, -a], [t, y, a], [-t, y, a]],
    [[-a, y, -t], [a, y, -t], [a, y, t], [-a, y, t]],
  ];
  const positions: number[] = [];
  const normals: number[] = [];
  for (const f of quads) {
    for (const tri of [
      [f[0], f[1], f[2]],
      [f[0], f[2], f[3]],
    ]) {
      for (const v of tri) {
        positions.push(v![0], v![1], v![2]);
        normals.push(0, 1, 0);
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
  g.computeBoundingSphere();
  return g;
}

function makeHealthMesh(): Group {
  const bodyColor = new Color(HEX.raceLine);
  const bodyMat = createCelMaterial({
    name: 'healthBox',
    color: bodyColor,
    rampColors: [
      bodyColor.clone().multiplyScalar(0.65),
      bodyColor.clone().multiplyScalar(1.0),
      bodyColor.clone().multiplyScalar(1.35),
      new Color(HEX.foam),
    ],
    flatShading: true,
    rimColor: PAL.foam,
    rimPower: 1.6,
    rimStrength: 0.9,
    outlineWidthPx: 3.2,
  });
  const body = new Mesh(boxGeo(0.95, 0.7, 0.95));
  body.userData.objectId = nextObjectId();
  applyCel(body, bodyMat);

  const plusColor = new Color(HEX.foam);
  const plusMat = createCelMaterial({
    name: 'healthPlus',
    color: plusColor,
    rampColors: [
      plusColor.clone().multiplyScalar(0.8),
      plusColor,
      plusColor.clone().multiplyScalar(1.2),
      new Color(0xffffff),
    ],
    flatShading: true,
    outlineWidthPx: 2.2,
    rimStrength: 0.5,
  });
  const plus = new Mesh(plusGeo());
  plus.userData.objectId = nextObjectId();
  applyCel(plus, plusMat);

  const root = new Group();
  root.add(body);
  root.add(plus);
  root.scale.setScalar(1.35);
  root.visible = false;
  return root;
}

const _tpScratch = {
  position: new Vector3(),
  tangent: new Vector3(0, 0, 1),
  curvature: 0,
  u: 0,
};

export class HealthBoxField implements Subsystem {
  readonly name = 'healthBoxes';
  readonly order = 42;

  private slots: Slot[] = [];
  private rng = new Rng(0x4e41_4c54);
  private ready = false;
  private track: TrackAPI | null = null;

  init(ctx: GameContext) {
    this.track = ctx.track;
    const n = COMBAT.healthBox.count;
    for (let i = 0; i < n; i++) {
      const root = makeHealthMesh();
      ctx.scene.add(root);
      this.slots.push({
        alive: false,
        x: 0,
        y: 0,
        z: 0,
        respawnAt: 0,
        root,
      });
    }
    this.reseedAll(ctx);
    this.ready = true;
  }

  reset(ctx?: GameContext) {
    const salt = Math.floor((ctx?.time ?? Math.random()) * 1000) >>> 0;
    this.rng = new Rng(0x4e414c54 ^ salt);
    if (ctx) this.reseedAll(ctx);
    else {
      for (const s of this.slots) {
        s.alive = true;
        s.respawnAt = 0;
        s.root.visible = true;
      }
    }
  }

  private reseedAll(ctx: GameContext) {
    for (const s of this.slots) this.placeRandom(s, ctx);
  }

  private placeRandom(slot: Slot, ctx: GameContext) {
    const H = COMBAT.healthBox;
    const track = this.track ?? ctx.track;
    const clear = H.startClearance;
    const usable = Math.max(40, track.length - clear * 2);
    const d = clear + this.rng.next() * usable;
    const pt = track.sampleDistance(d, _tpScratch);
    const tx = pt.tangent.x;
    const tz = pt.tangent.z;
    const lateral = this.rng.sym(H.lateralMax);
    const rx = tz;
    const rz = -tx;
    slot.x = pt.position.x + rx * lateral;
    slot.z = pt.position.z + rz * lateral;
    const deckY =
      typeof track.heightAt === 'function'
        ? track.heightAt(pt.u)
        : pt.position.y;
    slot.y = deckY + H.hoverY;
    slot.alive = true;
    slot.respawnAt = 0;
    slot.root.visible = true;
    slot.root.position.set(slot.x, slot.y, slot.z);
  }

  update(ctx: GameContext) {
    if (!this.ready) return;
    const H = COMBAT.healthBox;
    const t = ctx.time;
    const r2 = H.radius * H.radius;

    if (ctx.pickupHud) {
      ctx.pickupHud.flash = Math.max(0, ctx.pickupHud.flash - ctx.dt);
      if (ctx.pickupHud.flash <= 0) ctx.pickupHud = null;
    }

    if (ctx.phase !== 'racing' && ctx.phase !== 'countdown') {
      for (const s of this.slots) {
        s.root.visible = s.alive;
        if (s.alive) {
          const bob = Math.sin(t * 2.6 + s.x * 0.08) * H.bobAmp;
          s.root.position.y = s.y + bob;
          s.root.rotation.y = t * 0.9;
        }
      }
      return;
    }

    for (const s of this.slots) {
      if (!s.alive) {
        if (t >= s.respawnAt) this.placeRandom(s, ctx);
        else continue;
      }

      const bob = Math.sin(t * 2.6 + s.x * 0.08) * H.bobAmp;
      s.root.position.set(s.x, s.y + bob, s.z);
      s.root.rotation.y = t * 0.9;
      s.root.rotation.x = Math.sin(t * 1.7 + s.z * 0.05) * 0.1;

      // Prefer the player; AI only top up when critically damaged so rocket
      // hits aren't erased by vacuuming every pad on the racing line.
      const candidates = ctx.racers
        .filter((r) => {
          if (r.destroyed || r.finished) return false;
          if (r.hull.hp >= r.hull.maxHp - 0.5) return false;
          if (!r.isPlayer && r.hull.hp / r.hull.maxHp > 0.42) return false;
          const dx = r.state.position.x - s.x;
          const dz = r.state.position.z - s.z;
          return dx * dx + dz * dz <= r2;
        })
        .sort((a, b) => Number(b.isPlayer) - Number(a.isPlayer));

      const r = candidates[0];
      if (r) {
        repairHull(r.hull, {
          zoneAmount: r.isPlayer ? H.zoneRepair : H.zoneRepair * 0.45,
          traumaRelief: H.traumaRelief,
        });
        r.state.hp = r.hull.hp;
        r.state.maxHp = r.hull.maxHp;
        s.alive = false;
        s.root.visible = false;
        s.respawnAt = t + H.respawnSec;
        ctx.audio?.checkpoint();
        if (r.isPlayer) {
          ctx.pickupHud = { label: 'REPAIR', flash: 1.25 };
          ctx.cameraRig?.addShake(0.08);
        }
      }
    }
  }

  dispose() {
    for (const s of this.slots) {
      s.root.removeFromParent();
      s.alive = false;
    }
    this.slots.length = 0;
    this.ready = false;
  }
}
