/**
 * Animated lock / unlock HUD — screen reticles, acquire sweep, shatter burst.
 */

import { HEX } from '../core/palette';
import { clamp01 } from '../core/mathx';
import { FONT_STACK, inkText, rgba } from './inkDraw';

export type LockHudInput = {
  /** CSS pixel size of the HUD canvas. */
  w: number;
  h: number;
  s: number;
  time: number;
  /** Target name while locking out. */
  lockName: string | null;
  lockStrength: number;
  lockHitChance: number;
  /** NDC-projected screen pos of lock target, or null if offscreen. */
  lockX: number | null;
  lockY: number | null;
  incoming: boolean;
  breakMeter: number;
  breakFlash: number;
  lockImmune: boolean;
  /** True when lock + ammo + cooldown allow a guided shot. */
  canFire?: boolean;
  /** True while F is held waiting for lock to finish. */
  holdPending?: boolean;
  /** Locked rival hull (for integrity readout under reticle). */
  lockHp?: number | null;
  lockMaxHp?: number | null;
};

/** Mutable anim state owned by Hud. */
export type LockHudAnim = {
  appear: number;
  readyPunch: number;
  wasReady: boolean;
  breakBurst: number;
  lastBreakFlash: number;
  threatAppear: number;
  spin: number;
};

export function createLockHudAnim(): LockHudAnim {
  return {
    appear: 0,
    readyPunch: 0,
    wasReady: false,
    breakBurst: 0,
    lastBreakFlash: 0,
    threatAppear: 0,
    spin: 0,
  };
}

export function tickLockHudAnim(a: LockHudAnim, inp: LockHudInput, dt: number): void {
  const locking = !!inp.lockName;
  a.appear += ((locking ? 1 : 0) - a.appear) * Math.min(1, dt * 8);
  a.threatAppear += ((inp.incoming || inp.breakFlash > 0 || inp.lockImmune ? 1 : 0) - a.threatAppear) *
    Math.min(1, dt * 7);
  a.spin += dt;

  // Only punch when the rack can actually fire — not merely while painting.
  const ready = !!inp.canFire;
  if (ready && !a.wasReady) a.readyPunch = 1;
  a.wasReady = ready;
  a.readyPunch = Math.max(0, a.readyPunch - dt * 2.2);

  if (inp.breakFlash > a.lastBreakFlash + 0.05) a.breakBurst = 1;
  a.lastBreakFlash = inp.breakFlash;
  a.breakBurst = Math.max(0, a.breakBurst - dt * 1.35);
}

function cornerBracket(
  g: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  half: number,
  len: number,
  thick: number,
  color: string,
  open: number,
) {
  // open 0 = tight on target, 1 = wide
  const o = half + open * half * 0.85;
  g.strokeStyle = color;
  g.lineWidth = thick;
  g.lineCap = 'square';
  g.beginPath();
  // TL
  g.moveTo(cx - o, cy - o + len);
  g.lineTo(cx - o, cy - o);
  g.lineTo(cx - o + len, cy - o);
  // TR
  g.moveTo(cx + o - len, cy - o);
  g.lineTo(cx + o, cy - o);
  g.lineTo(cx + o, cy - o + len);
  // BL
  g.moveTo(cx - o, cy + o - len);
  g.lineTo(cx - o, cy + o);
  g.lineTo(cx - o + len, cy + o);
  // BR
  g.moveTo(cx + o - len, cy + o);
  g.lineTo(cx + o, cy + o);
  g.lineTo(cx + o, cy + o - len);
  g.stroke();
}

function arcSweep(
  g: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  r: number,
  progress: number,
  time: number,
  color: string,
  thick: number,
) {
  const start = -Math.PI / 2 + time * 2.4;
  const span = progress * Math.PI * 1.85;
  g.strokeStyle = color;
  g.lineWidth = thick;
  g.beginPath();
  g.arc(cx, cy, r, start, start + span);
  g.stroke();
}

/**
 * Draw lock reticle + threat / break overlays. Returns true if anything drawn.
 */
export function drawLockHud(
  g: CanvasRenderingContext2D,
  a: LockHudAnim,
  inp: LockHudInput,
): void {
  const { s, w, h, time } = inp;

  // ── Outgoing lock reticle ───────────────────────────────────────────────
  if (a.appear > 0.02 && inp.lockName && inp.lockX != null && inp.lockY != null) {
    const cx = inp.lockX;
    const cy = inp.lockY;
    const str = clamp01(inp.lockStrength);
    const ready = !!inp.canFire || inp.lockHitChance >= 0.62;
    const punch = a.readyPunch;
    const open = (1 - str) * (1.15 - a.appear * 0.3);
    const half = (30 + (1 - str) * 24) * s * (1 + punch * 0.4);
    const len = (15 + str * 7) * s;
    const col = ready
      ? rgba(HEX.boostHot, 0.65 + a.appear * 0.35)
      : rgba(HEX.hull3, 0.4 + a.appear * 0.5);

    g.save();
    g.globalAlpha = a.appear;

    // Soft diamond
    g.strokeStyle = rgba(ready ? HEX.waterCrest : HEX.hudDim, 0.35 + str * 0.4);
    g.lineWidth = 1.4 * s;
    const d = half * 1.35;
    g.beginPath();
    g.moveTo(cx, cy - d);
    g.lineTo(cx + d, cy);
    g.lineTo(cx, cy + d);
    g.lineTo(cx - d, cy);
    g.closePath();
    g.stroke();

    arcSweep(
      g,
      cx,
      cy,
      half * 1.55,
      str,
      time,
      rgba(ready ? HEX.boostHot : HEX.hull3, 0.7),
      2.2 * s,
    );

    cornerBracket(g, cx, cy, half, len, (2.2 + punch * 2) * s, col, open);

    // Centre pip
    g.fillStyle = rgba(ready ? HEX.boostHot : HEX.foam, 0.9);
    const pip = (3 + str * 2 + punch * 4) * s;
    g.fillRect(cx - pip * 0.5, cy - pip * 0.5, pip, pip);

    // Name plate under reticle — include live hull so rocket hits read clearly.
    const hp =
      inp.lockHp != null && inp.lockMaxHp != null && inp.lockMaxHp > 0
        ? Math.round(inp.lockHp)
        : null;
    const label = ready
      ? hp != null
        ? `${inp.lockName}  ${hp} HP`
        : `${inp.lockName}  ${Math.round(inp.lockHitChance * 100)}%`
      : hp != null
        ? `${inp.lockName}  ${hp} HP · ${Math.round(str * 100)}%`
        : `${inp.lockName}  LOCK ${Math.round(str * 100)}%`;
    inkText(g, label, cx, cy + half + 22 * s, {
      font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
      fill: rgba(
        hp != null && hp < 40 ? HEX.warn : ready ? HEX.boostHot : HEX.hudPaper,
        0.95,
      ),
      align: 'center',
      tracking: 1.8 * s,
      ink: rgba(HEX.ink, 0.9),
      inkWidth: 2.4 * s,
    });
    if (hp != null && inp.lockMaxHp != null) {
      const bw = 72 * s;
      const bh = 5 * s;
      const bx = cx - bw * 0.5;
      const by = cy + half + 28 * s;
      const frac = clamp01(inp.lockHp! / inp.lockMaxHp);
      g.fillStyle = rgba(HEX.ink, 0.9);
      g.fillRect(bx, by, bw, bh);
      g.fillStyle = rgba(frac > 0.35 ? HEX.raceLine : HEX.warn, 0.95);
      g.fillRect(bx, by, bw * frac, bh);
      g.strokeStyle = rgba(HEX.hudPaper, 0.75);
      g.lineWidth = 1 * s;
      g.strokeRect(bx, by, bw, bh);
    }

    if (ready) {
      const flash = 0.7 + 0.3 * Math.sin(time * 18);
      const pw = 128 * s;
      const ph = 22 * s;
      const fireY = cy + half + (hp != null ? 36 : 28) * s;
      g.fillStyle = rgba(HEX.boost, 0.55 + flash * 0.35);
      g.strokeStyle = rgba(HEX.boostHot, flash);
      g.lineWidth = 2.2 * s;
      g.beginPath();
      g.moveTo(cx - pw * 0.5, fireY);
      g.lineTo(cx + pw * 0.5, fireY);
      g.lineTo(cx + pw * 0.5 - 8 * s, fireY + ph);
      g.lineTo(cx - pw * 0.5 + 8 * s, fireY + ph);
      g.closePath();
      g.fill();
      g.stroke();
      inkText(g, 'FIRE · F', cx, fireY + ph * 0.72, {
        font: `900 ${Math.round(13 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.foam, flash),
        align: 'center',
        tracking: 3 * s,
        ink: rgba(HEX.ink, 0.95),
        inkWidth: 2.4 * s,
      });
    } else if (inp.holdPending) {
      inkText(g, 'HOLD… LOCKING', cx, cy + half + 40 * s, {
        font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.waterCrest, 0.85 + 0.15 * Math.sin(time * 10)),
        align: 'center',
        tracking: 2 * s,
      });
    }

    // Ready snap rings
    if (punch > 0.01 || ready) {
      const ringA = ready ? 0.55 + 0.45 * Math.sin(time * 14) : punch;
      g.strokeStyle = rgba(HEX.boostHot, ringA);
      g.lineWidth = (ready ? 3.4 : 3) * s;
      g.beginPath();
      g.arc(cx, cy, half * (1.15 + (ready ? 0.15 : (1 - punch) * 1.8)), 0, Math.PI * 2);
      g.stroke();
    }

    g.restore();
  }

  // ── Incoming threat / drift-break ───────────────────────────────────────
  if (a.threatAppear > 0.02) {
    const cx = w * 0.5;
    const cy = h * 0.2;
    g.save();
    g.globalAlpha = a.threatAppear;

    if (a.breakBurst > 0.01 || inp.breakFlash > 0) {
      drawBreakBurst(g, cx, cy, s, a.breakBurst, time);
    } else if (inp.lockImmune) {
      inkText(g, 'SIGNAL JAMMED', cx, cy, {
        font: `800 ${Math.round(18 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.waterCrest, 0.9),
        align: 'center',
        tracking: 4 * s,
        ink: rgba(HEX.ink, 1),
        inkWidth: 3 * s,
      });
      // Fading immunity ring
      g.strokeStyle = rgba(HEX.waterCrest, 0.35 + 0.25 * Math.sin(time * 8));
      g.lineWidth = 2 * s;
      g.beginPath();
      g.arc(cx, cy + 28 * s, 36 * s, 0, Math.PI * 2);
      g.stroke();
    } else if (inp.incoming) {
      drawThreatLock(g, cx, cy, s, inp.breakMeter, time, a.spin);
    }

    g.restore();
  }
}

function drawThreatLock(
  g: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  s: number,
  meter: number,
  time: number,
  spin: number,
) {
  const blink = 0.7 + 0.3 * Math.sin(time * 12);
  const half = 42 * s;
  const open = 0.35 + (1 - clamp01(meter)) * 0.5;

  // Rotating threat brackets
  g.save();
  g.translate(cx, cy);
  g.rotate(spin * 0.9);
  cornerBracket(
    g,
    0,
    0,
    half,
    18 * s,
    2.6 * s,
    rgba(HEX.warn, blink),
    open,
  );
  g.restore();

  g.save();
  g.translate(cx, cy);
  g.rotate(-spin * 1.3);
  cornerBracket(
    g,
    0,
    0,
    half * 0.72,
    12 * s,
    1.8 * s,
    rgba(HEX.boostHot, blink * 0.7),
    open * 0.8,
  );
  g.restore();

  inkText(g, 'LOCKED ON', cx, cy - half - 14 * s, {
    font: `800 ${Math.round(14 * s)}px ${FONT_STACK}`,
    fill: rgba(HEX.warn, blink),
    align: 'center',
    tracking: 3 * s,
    ink: rgba(HEX.ink, 1),
    inkWidth: 2.8 * s,
  });
  inkText(g, 'DRIFT TO BREAK · Q+E', cx, cy + half + 18 * s, {
    font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
    fill: rgba(HEX.hudPaper, 0.9),
    align: 'center',
    tracking: 2.4 * s,
  });

  // Break meter as arc
  const m = clamp01(meter);
  g.strokeStyle = rgba(HEX.hudInk, 0.9);
  g.lineWidth = 7 * s;
  g.beginPath();
  g.arc(cx, cy, half * 1.25, Math.PI * 0.15, Math.PI * 0.85);
  g.stroke();
  g.strokeStyle = rgba(HEX.boostHot, 0.95);
  g.lineWidth = 5 * s;
  g.beginPath();
  g.arc(cx, cy, half * 1.25, Math.PI * 0.15, Math.PI * 0.15 + m * Math.PI * 0.7);
  g.stroke();
}

function drawBreakBurst(
  g: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  s: number,
  burst: number,
  time: number,
) {
  const t = 1 - burst;
  const expand = 20 * s + t * 120 * s;

  // Shattering corner shards flying out
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2 + time;
    const dist = expand * (0.6 + (i % 3) * 0.15);
    const x = cx + Math.cos(ang) * dist;
    const y = cy + Math.sin(ang) * dist;
    g.strokeStyle = rgba(HEX.raceLine, burst * 0.9);
    g.lineWidth = 2.4 * s;
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + Math.cos(ang + 0.4) * 14 * s, y + Math.sin(ang + 0.4) * 14 * s);
    g.stroke();
  }

  g.strokeStyle = rgba(HEX.foam, burst);
  g.lineWidth = 3 * s;
  g.beginPath();
  g.arc(cx, cy, expand * 0.55, 0, Math.PI * 2);
  g.stroke();
  g.strokeStyle = rgba(HEX.waterCrest, burst * 0.7);
  g.beginPath();
  g.arc(cx, cy, expand * 0.9, 0, Math.PI * 2);
  g.stroke();

  inkText(g, 'LOCK BROKEN', cx, cy, {
    font: `800 ${Math.round(20 * s)}px ${FONT_STACK}`,
    fill: rgba(HEX.raceLine, 0.5 + burst * 0.5),
    align: 'center',
    tracking: 4 * s,
    ink: rgba(HEX.ink, 1),
    inkWidth: 3.2 * s,
  });
}
