/**
 * Pure nitro charge helpers — no Three / mode imports.
 */

import type { ShipState } from '../core/types';
import { NITRO_DEFAULTS, type NitroCharge, type NitroTuning } from './types';

export function createNitroCharge(tuning: Partial<NitroTuning> = {}): NitroCharge {
  const max = tuning.charges ?? NITRO_DEFAULTS.charges;
  return {
    remaining: max,
    max,
    igniteFlash: 0,
    readyPulse: 0,
  };
}

export function resetNitroCharge(n: NitroCharge, tuning: Partial<NitroTuning> = {}): void {
  const max = tuning.charges ?? n.max;
  n.max = max;
  n.remaining = max;
  n.igniteFlash = 0;
  n.readyPulse = 0;
}

export function tickNitroCharge(n: NitroCharge, dt: number): void {
  n.igniteFlash = Math.max(0, n.igniteFlash - dt);
  if (n.remaining > 0) n.readyPulse = (n.readyPulse + dt) % 1000;
  else n.readyPulse = 0;
}

export function tryActivateNitro(
  n: NitroCharge,
  state: ShipState,
  tuning: Partial<NitroTuning> = {},
): boolean {
  const t = { ...NITRO_DEFAULTS, ...tuning };
  if (n.remaining <= 0) return false;
  if (state.nitroTime > 0.05) return false;

  n.remaining -= 1;
  n.igniteFlash = 1.1;
  state.nitroTime = t.duration;

  const fx = Math.sin(state.heading);
  const fz = Math.cos(state.heading);
  state.velocity.x += fx * t.kick;
  state.velocity.z += fz * t.kick;
  state.forwardSpeed += t.kick;
  return true;
}

export function nitroAccel(
  state: ShipState,
  mass: number,
  tuning: Partial<NitroTuning> = {},
): number {
  if (state.nitroTime <= 0) return 0;
  const force = tuning.force ?? NITRO_DEFAULTS.force;
  return force / mass;
}

export function nitroSpeedMul(state: ShipState, tuning: Partial<NitroTuning> = {}): number {
  if (state.nitroTime <= 0) return 1;
  return tuning.topSpeedMul ?? NITRO_DEFAULTS.topSpeedMul;
}

export function tickNitroBurn(state: ShipState, dt: number): void {
  if (state.nitroTime > 0) state.nitroTime = Math.max(0, state.nitroTime - dt);
}
