/**
 * Lightweight 3D circuit preview for the title screen.
 * Owns a dedicated canvas layered above the HUD so #gl stays free for the race.
 */

import {
  Color,
  Group,
  HemisphereLight,
  Material,
  Mesh,
  PerspectiveCamera,
  Scene,
  SRGBColorSpace,
  Vector3,
  WebGLRenderer,
  type Object3D,
} from 'three';
import { HEX } from '../core/palette';
import { Track, type TrackLayout } from '../race/track';
import { SHARED } from '../render/celMaterial';
import { createRaceFloor } from '../world/raceFloor';

export type PreviewRect = { x: number; y: number; w: number; h: number };

function disposeObject(obj: Object3D) {
  obj.traverse((child) => {
    const mesh = child as Mesh;
    if (mesh.isMesh) {
      mesh.geometry?.dispose();
      const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const m of mats) {
        if (m && (m as Material).dispose) (m as Material).dispose();
      }
    }
  });
}

export class TrackPreview3D {
  private readonly canvas: HTMLCanvasElement;
  private readonly renderer: WebGLRenderer;
  private readonly scene = new Scene();
  private readonly camera = new PerspectiveCamera(32, 1, 2, 6000);
  private readonly root = new Group();
  private readonly look = new Vector3();

  private track: Track | null = null;
  private floor: Group | null = null;
  private layoutKey = '';
  private pending: TrackLayout | null = null;
  private rebuildTimer = 0;
  private ready = false;
  private span = 200;
  private readonly t0 = performance.now();

  constructor(host: HTMLElement = document.getElementById('app') ?? document.body) {
    this.canvas = document.createElement('canvas');
    this.canvas.id = 'track-preview';
    this.canvas.setAttribute('aria-hidden', 'true');
    this.canvas.style.cssText = [
      'position:absolute',
      'left:0',
      'top:0',
      'width:0',
      'height:0',
      'pointer-events:none',
      // Above HUD so we never depend on a transparent hole punching through opaque plates.
      'z-index:6',
      'border-radius:8px',
      'overflow:hidden',
      'opacity:0',
      'box-sizing:border-box',
      'border:2px solid rgba(168,216,255,0.55)',
      'background:#081426',
    ].join(';');
    host.appendChild(this.canvas);

    this.renderer = new WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      alpha: false,
      stencil: false,
      depth: true,
      powerPreference: 'high-performance',
    });
    this.renderer.outputColorSpace = SRGBColorSpace;
    this.renderer.setClearColor(new Color(HEX.hudInk), 1);
    this.renderer.autoClear = true;
    this.renderer.shadowMap.enabled = false;

    this.scene.background = new Color(HEX.hudInk);
    this.scene.add(new HemisphereLight(0xa8d8ff, 0x2a1040, 0.55));
    this.scene.add(this.root);
  }

  get isReady(): boolean {
    return this.ready;
  }

  /**
   * Queue a layout rebuild. Pass `immediate` after BUILD so the new circuit
   * appears without waiting on the debounce used for option spam.
   */
  setLayout(layout: TrackLayout, immediate = false) {
    const key = layoutKey(layout);
    if (key === this.layoutKey && this.track && !this.pending) return;

    this.pending = layout;
    // Hide stale mesh right away — caller falls back to the 2D outline of `layout`.
    this.ready = false;
    this.canvas.style.opacity = '0';

    window.clearTimeout(this.rebuildTimer);
    if (immediate) {
      this.flushRebuild();
      return;
    }
    this.rebuildTimer = window.setTimeout(() => this.flushRebuild(), 50);
  }

  setAccent(cssColor: string) {
    this.canvas.style.borderColor = cssColor;
  }

  private flushRebuild() {
    const layout = this.pending;
    this.pending = null;
    if (!layout) return;
    const key = layoutKey(layout);

    this.clearRoot();
    try {
      const track = new Track(layout);
      const floor = createRaceFloor(track);
      const ribbon = track.group.getObjectByName('racingLine');
      if (ribbon) ribbon.visible = false;

      this.root.add(floor);
      this.root.add(track.group);
      this.track = track;
      this.floor = floor;
      this.layoutKey = key;
      this.fitBounds();
      this.ready = true;
    } catch (err) {
      console.warn('[TrackPreview3D] rebuild failed', err);
      this.ready = false;
      this.layoutKey = '';
      this.canvas.style.opacity = '0';
    }
  }

  private fitBounds() {
    if (!this.track) return;
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;
    let minZ = Infinity;
    let maxZ = -Infinity;
    const n = 128;
    const tp = this.track.sample(0);
    for (let i = 0; i < n; i++) {
      this.track.sample(i / n, tp);
      const p = tp.position;
      if (p.x < minX) minX = p.x;
      if (p.x > maxX) maxX = p.x;
      if (p.y < minY) minY = p.y;
      if (p.y > maxY) maxY = p.y;
      if (p.z < minZ) minZ = p.z;
      if (p.z > maxZ) maxZ = p.z;
    }
    this.look.set((minX + maxX) * 0.5, (minY + maxY) * 0.5 + 2, (minZ + maxZ) * 0.5);
    const spanX = Math.max(1, maxX - minX);
    const spanZ = Math.max(1, maxZ - minZ);
    const spanY = Math.max(8, maxY - minY);
    this.span = Math.max(spanX, spanZ, spanY * 2.5) * 0.58 + 48;
  }

  /** Position over `rect` (CSS px) and render. True when the live mesh is showing. */
  render(rect: PreviewRect): boolean {
    if (this.pending) this.flushRebuild();

    if (!this.ready || !this.track || rect.w < 8 || rect.h < 8) {
      this.canvas.style.opacity = '0';
      return false;
    }

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.style.left = `${Math.round(rect.x)}px`;
    this.canvas.style.top = `${Math.round(rect.y)}px`;
    this.canvas.style.width = `${Math.round(rect.w)}px`;
    this.canvas.style.height = `${Math.round(rect.h)}px`;
    this.canvas.style.opacity = '1';

    const bufW = Math.max(1, Math.floor(rect.w * dpr));
    const bufH = Math.max(1, Math.floor(rect.h * dpr));
    if (this.canvas.width !== bufW || this.canvas.height !== bufH) {
      this.renderer.setPixelRatio(dpr);
      this.renderer.setSize(rect.w, rect.h, false);
    }

    const t = (performance.now() - this.t0) / 1000;
    const yaw = t * 0.35;
    const pitch = 0.78;
    const dist = this.span * 2.25;
    this.camera.position.set(
      this.look.x + Math.cos(yaw) * Math.cos(pitch) * dist,
      this.look.y + Math.sin(pitch) * dist,
      this.look.z + Math.sin(yaw) * Math.cos(pitch) * dist,
    );
    this.camera.lookAt(this.look);
    this.camera.aspect = rect.w / Math.max(1, rect.h);
    this.camera.near = Math.max(1, dist * 0.015);
    this.camera.far = Math.max(4000, dist * 10);
    this.camera.updateProjectionMatrix();

    SHARED.uTime.value = t;
    SHARED.uCameraPos.value.copy(this.camera.position);
    SHARED.uResolution.value.set(bufW, bufH);
    SHARED.uTanHalfFov.value = Math.tan((this.camera.fov * Math.PI) / 360);
    SHARED.uNear.value = this.camera.near;
    SHARED.uFar.value = this.camera.far;

    this.renderer.render(this.scene, this.camera);
    return true;
  }

  private clearRoot() {
    while (this.root.children.length) {
      const child = this.root.children[0]!;
      this.root.remove(child);
      disposeObject(child);
    }
    this.track = null;
    this.floor = null;
    this.layoutKey = '';
    this.ready = false;
  }

  dispose() {
    window.clearTimeout(this.rebuildTimer);
    this.pending = null;
    this.clearRoot();
    this.renderer.dispose();
    this.canvas.remove();
  }
}

function layoutKey(layout: TrackLayout): string {
  // Include scale so regenerates with the same seed-looking id still refresh.
  const scale = layout.layoutScale ?? '';
  return `${layout.id}:${scale}:${layout.relief ?? ''}:${layout.gateCount ?? ''}:${layout.verts.length}`;
}
