/**
 * Shared Web Audio unlock — iOS Safari is strict: create/resume AND play a
 * real buffer source must happen synchronously inside the gesture handler.
 * Awaiting before those calls leaves the context "running" but muted.
 */

let shared: AudioContext | null = null;
let disarmUnlock: (() => void) | null = null;
let pendingOnUnlocked: (() => void) | null = null;
let stateWatchWired = false;
/** True after a gesture successfully primed output (even if resume is pending). */
let primed = false;

function getCtor(): typeof AudioContext | null {
  const w = window as Window & { webkitAudioContext?: typeof AudioContext };
  return window.AudioContext ?? w.webkitAudioContext ?? null;
}

/** True when the live context is running and can schedule sound. */
export function audioIsRunning(): boolean {
  return shared?.state === 'running' && primed;
}

export function getSharedAudioContext(): AudioContext | null {
  return shared;
}

function needsResume(ac: AudioContext): boolean {
  const st = ac.state as AudioContextState | 'interrupted';
  return st === 'suspended' || st === 'interrupted';
}

/** Must run inside the user-gesture turn — not after await. */
function primeOutputSync(ac: AudioContext) {
  try {
    const buf = ac.createBuffer(1, 1, 22050);
    const src = ac.createBufferSource();
    src.buffer = buf;
    src.connect(ac.destination);
    src.start(0);
    primed = true;
  } catch {
    /* ignore */
  }
}

/**
 * Create + resume kick + silent play — all synchronous in the gesture stack.
 * Returns the context (may still be settling toward 'running').
 */
export function unlockAudioSync(): AudioContext | null {
  const Ctor = getCtor();
  if (!Ctor) return null;

  if (!shared) {
    try {
      shared = new Ctor({ latencyHint: 'interactive' });
    } catch {
      shared = new Ctor();
    }
    wireStateWatch(shared);
  }

  if (needsResume(shared)) {
    // Do not await — the sync call is what iOS counts as the gesture unlock.
    void shared.resume();
  }

  primeOutputSync(shared);
  return shared;
}

function wireStateWatch(ac: AudioContext) {
  if (stateWatchWired) return;
  stateWatchWired = true;
  ac.addEventListener('statechange', () => {
    if (needsResume(ac)) {
      primed = false;
      armAudioUnlock(pendingOnUnlocked ?? undefined);
    }
  });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && shared && needsResume(shared)) {
      primed = false;
      armAudioUnlock(pendingOnUnlocked ?? undefined);
    }
  });
}

/**
 * Async helper for code that needs a running context after unlock.
 * Prefer calling unlockAudioSync() first from the gesture itself.
 */
export async function unlockSharedAudio(): Promise<AudioContext | null> {
  const ac = shared ?? unlockAudioSync();
  if (!ac) return null;

  if (needsResume(ac)) {
    try {
      await ac.resume();
    } catch (err) {
      console.warn('[audio] resume failed', err);
      return null;
    }
  }

  if (ac.state !== 'running') return null;
  if (!primed) primeOutputSync(ac);
  return ac;
}

/** Wire document-level gestures until audio is running. Returns a disposer. */
export function armAudioUnlock(onUnlocked?: () => void): () => void {
  if (onUnlocked) pendingOnUnlocked = onUnlocked;
  disarmUnlock?.();

  let done = false;
  const opts: AddEventListenerOptions = { capture: true, passive: true };

  const tryUnlock = () => {
    // Everything critical happens sync in this turn.
    const ac = unlockAudioSync();
    if (!ac) return;

    const finish = () => {
      if (done) return;
      if (ac.state === 'running' && primed) {
        done = true;
        remove();
        pendingOnUnlocked?.();
      }
    };

    finish();
    if (!done) {
      void ac.resume().then(finish).catch(() => undefined);
      // Also poll briefly — some iOS builds flip state without firing then.
      let n = 0;
      const poll = () => {
        finish();
        if (!done && n++ < 20) window.setTimeout(poll, 50);
      };
      window.setTimeout(poll, 0);
    }
  };

  const remove = () => {
    document.removeEventListener('pointerdown', tryUnlock, opts);
    document.removeEventListener('touchstart', tryUnlock, opts);
    document.removeEventListener('touchend', tryUnlock, opts);
    document.removeEventListener('keydown', tryUnlock, opts);
    document.removeEventListener('click', tryUnlock, opts);
    if (disarmUnlock === remove) disarmUnlock = null;
  };
  disarmUnlock = remove;

  // touchstart is the most reliable iOS gesture for audio unlock.
  document.addEventListener('touchstart', tryUnlock, opts);
  document.addEventListener('pointerdown', tryUnlock, opts);
  document.addEventListener('touchend', tryUnlock, opts);
  document.addEventListener('keydown', tryUnlock, opts);
  document.addEventListener('click', tryUnlock, opts);

  if (shared?.state === 'running' && primed) {
    done = true;
    remove();
    pendingOnUnlocked?.();
  }

  return remove;
}
