/**
 * Cel-shaded thruster traces behind every craft.
 *
 * Temporary ribbon wakes — hard alpha bands (not soft PNG fades), ink outlines,
 * per-racer identity colour. Twin stern emitters; boost lengthens and heats the trail.
 */

import {
  BufferAttribute,
  BufferGeometry,
  DynamicDrawUsage,
  Group,
  Mesh,
  Vector3,
} from 'three';
import { HEX, PAL, RACER_COLORS } from '../core/palette';
import { clamp01 } from '../core/mathx';
import type { GameContext, Racer, Subsystem } from '../core/types';
import { applyCel, createCelMaterial, type CelMaterialSet } from '../render/celMaterial';
import { SHIP_MESH_SCALE, SHIP_MESH_Y } from '../ship/shipMesh';

const POINTS = 28;
const MIN_STEP = 0.55;
const BASE_LIFE = 0.85;
const BOOST_LIFE = 1.35;
const HALF_W = 0.22;
const BOOST_HALF_W = 0.38;
const SPREAD = 1.8;

type Sample = {
  x: number;
  y: number;
  z: number;
  /** Unit along travel (forward at push time). */
  fx: number;
  fz: number;
  age: number;
  alive: boolean;
  boost: boolean;
};

type Ribbon = {
  racerId: number;
  /** -1 port / +1 starboard thruster. */
  side: number;
  mesh: Mesh;
  mat: CelMaterialSet;
  samples: Sample[];
  head: number;
  count: number;
  distAcc: number;
  posAttr: BufferAttribute;
  norAttr: BufferAttribute;
};

const _prev = new Vector3();
const _cur = new Vector3();
const _right = new Vector3();

export class TrailFx implements Subsystem {
  readonly name = 'trailFx';
  readonly order = 70;
  private root = new Group();
  private ribbons: Ribbon[] = [];
  private ready = false;

  init(ctx: GameContext) {
    this.root.name = 'celTrails';
    ctx.scene.add(this.root);
    for (const r of ctx.racers) {
      this.ribbons.push(this.makeRibbon(r, -1));
      this.ribbons.push(this.makeRibbon(r, 1));
    }
    this.ready = true;
  }

  private makeRibbon(r: Racer, side: number): Ribbon {
    const nVert = POINTS * 2;
    const pos = new Float32Array(nVert * 3);
    const nor = new Float32Array(nVert * 3);
    for (let i = 0; i < nor.length; i += 3) nor[i + 1] = 1;

    const idx: number[] = [];
    for (let i = 0; i < POINTS - 1; i++) {
      const a = i * 2;
      idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }

    const geo = new BufferGeometry();
    const posAttr = new BufferAttribute(pos, 3);
    posAttr.setUsage(DynamicDrawUsage);
    const norAttr = new BufferAttribute(nor, 3);
    norAttr.setUsage(DynamicDrawUsage);
    geo.setAttribute('position', posAttr);
    geo.setAttribute('normal', norAttr);
    geo.setIndex(idx);
    geo.computeBoundingSphere();

    const hull = RACER_COLORS[r.id % RACER_COLORS.length].hull;
    const boost = PAL.boost;
    const mat = createCelMaterial({
      color: hull,
      rampColors: [hull.clone().multiplyScalar(0.55), hull, boost.clone().multiplyScalar(0.85), PAL.boostHot],
      outlineWidthPx: 1.6,
      rimStrength: 0.55,
      specSize: 0.9,
      transparent: true,
      opacity: 1,
      edgeBias: 0.85,
    });
    // Hard-band opacity in the fragment — age is packed into vertex color via
    // a custom uniform updated per-ribbon rewrite isn't needed; we collapse
    // dead segments to zero width instead (cel-friendly dissipation).

    const mesh = new Mesh(geo);
    mesh.name = `trail-${r.id}`;
    mesh.frustumCulled = false;
    mesh.renderOrder = 3;
    applyCel(mesh, mat, 3);
    mat.main.depthWrite = false;
    mat.main.transparent = true;
    if (mat.outline) {
      mat.outline.depthWrite = false;
      mat.outline.transparent = true;
    }
    this.root.add(mesh);

    const samples: Sample[] = [];
    for (let i = 0; i < POINTS; i++) {
      samples.push({
        x: 0,
        y: 0,
        z: 0,
        fx: 0,
        fz: 1,
        age: 99,
        alive: false,
        boost: false,
      });
    }

    return {
      racerId: r.id,
      side,
      mesh,
      mat,
      samples,
      head: 0,
      count: 0,
      distAcc: 0,
      posAttr,
      norAttr,
    };
  }

  update(ctx: GameContext) {
    if (!this.ready) return;

    // Twin ribbons per racer (port + starboard thrusters)
    while (this.ribbons.length < ctx.racers.length * 2) {
      const r = ctx.racers[Math.floor(this.ribbons.length / 2)];
      const side = this.ribbons.length % 2 === 0 ? -1 : 1;
      this.ribbons.push(this.makeRibbon(r, side));
    }

    for (const rib of this.ribbons) {
      const r = ctx.racers.find((x) => x.id === rib.racerId);
      if (r) this.stepRibbon(ctx, r, rib);
    }
  }

  private stepRibbon(ctx: GameContext, r: Racer, rib: Ribbon) {
    const dt = ctx.dt;
    const st = r.state;
    if (r.destroyed) {
      for (const s of rib.samples) s.alive = false;
      rib.mesh.visible = false;
      return;
    }
    rib.mesh.visible = true;
    const moving = Math.abs(st.forwardSpeed) > 3 || st.boosting;
    const emitting = moving && (st.appliedThrottle > 0.08 || st.boosting || Math.abs(st.forwardSpeed) > 12);

    // Age samples
    const maxLife = st.boosting ? BOOST_LIFE : BASE_LIFE;
    for (const s of rib.samples) {
      if (!s.alive) continue;
      s.age += dt;
      if (s.age > maxLife * (s.boost ? 1.25 : 1)) s.alive = false;
    }

    if (emitting) {
      const hx = Math.sin(st.heading);
      const hz = Math.cos(st.heading);
      const rx = hz;
      const rz = -hx;
      // Twin corner thrusters — craft-local (±0.85, y≈0.16, z≈-3.0) × mesh scale.
      const lat = rib.side * 0.85 * SHIP_MESH_SCALE;
      const back = 3.0 * SHIP_MESH_SCALE;
      const sx = st.position.x - hx * back + rx * lat;
      const sy = st.position.y + SHIP_MESH_Y + 0.16 * SHIP_MESH_SCALE;
      const sz = st.position.z - hz * back + rz * lat;

      if (rib.count > 0) {
        const last = rib.samples[(rib.head - 1 + POINTS) % POINTS];
        const dx = sx - last.x;
        const dz = sz - last.z;
        rib.distAcc += Math.hypot(dx, dz);
      } else {
        rib.distAcc = MIN_STEP;
      }

      const step = st.boosting ? MIN_STEP * 0.65 : MIN_STEP;
      if (rib.distAcc >= step) {
        rib.distAcc = 0;
        const slot = rib.head % POINTS;
        const s = rib.samples[slot];
        s.x = sx;
        s.y = sy;
        s.z = sz;
        s.fx = hx;
        s.fz = hz;
        s.age = 0;
        s.alive = true;
        s.boost = st.boosting;
        rib.head = (rib.head + 1) % POINTS;
        if (rib.count < POINTS) rib.count++;
      }
    }

    this.rewrite(rib, st.boosting);
  }

  private rewrite(rib: Ribbon, boostingNow: boolean) {
    const pos = rib.posAttr.array as Float32Array;
    const nor = rib.norAttr.array as Float32Array;

    // Collect alive samples oldest → newest (tight pack — never bridge dead gaps)
    const live: Sample[] = [];
    for (let i = 0; i < rib.count; i++) {
      const idx = (rib.head - rib.count + i + POINTS * 2) % POINTS;
      const s = rib.samples[idx];
      if (s.alive) live.push(s);
    }

    let lastLx = 0;
    let lastLy = -999;
    let lastLz = 0;
    let lastRx = 0;
    let lastRy = -999;
    let lastRz = 0;

    for (let i = 0; i < POINTS; i++) {
      const o = i * 6;
      const s = live[i];
      if (!s || live.length < 2) {
        pos[o] = lastLx;
        pos[o + 1] = lastLy;
        pos[o + 2] = lastLz;
        pos[o + 3] = lastRx;
        pos[o + 4] = lastRy;
        pos[o + 5] = lastRz;
        continue;
      }

      _right.set(s.fz, 0, -s.fx);
      const maxLife = s.boost ? BOOST_LIFE : BASE_LIFE;
      const t = clamp01(s.age / maxLife);
      // Hard cel bands — 4 width steps, then gone
      const band = t < 0.18 ? 1 : t < 0.4 ? 0.72 : t < 0.65 ? 0.42 : t < 0.85 ? 0.2 : 0;
      if (band <= 0) {
        pos[o] = lastLx;
        pos[o + 1] = lastLy;
        pos[o + 2] = lastLz;
        pos[o + 3] = lastRx;
        pos[o + 4] = lastRy;
        pos[o + 5] = lastRz;
        continue;
      }

      const baseW = (s.boost || boostingNow ? BOOST_HALF_W : HALF_W) * band;
      const hw = baseW * (1 + t * SPREAD);
      const lift = t * t * 1.1;

      lastLx = s.x - _right.x * hw;
      lastLy = s.y + lift;
      lastLz = s.z - _right.z * hw;
      lastRx = s.x + _right.x * hw;
      lastRy = s.y + lift;
      lastRz = s.z + _right.z * hw;

      pos[o] = lastLx;
      pos[o + 1] = lastLy;
      pos[o + 2] = lastLz;
      pos[o + 3] = lastRx;
      pos[o + 4] = lastRy;
      pos[o + 5] = lastRz;

      nor[o] = nor[o + 3] = 0;
      nor[o + 1] = nor[o + 4] = 1;
      nor[o + 2] = nor[o + 5] = 0;
    }

    rib.posAttr.needsUpdate = true;
    rib.norAttr.needsUpdate = true;
    rib.mesh.geometry.computeBoundingSphere();

    const hull = RACER_COLORS[rib.racerId % RACER_COLORS.length];
    const hot = boostingNow ? PAL.boostHot : hull.hull;
    rib.mat.uniforms.uColor.value.copy(hot);
    rib.mat.uniforms.uOpacity.value = boostingNow ? 1 : 0.92;
    void HEX;
    void _prev;
    void _cur;
  }

  dispose() {
    for (const r of this.ribbons) {
      r.mesh.geometry.dispose();
    }
    this.ribbons.length = 0;
  }
}
