/**
 * Hull integrity — zoned damage, directional collisions, handling penalties.
 * WaveKill Race Assault port, adapted for WaveSpace ShipState.hp.
 *
 * Tunables live in `core/combatTune.ts`.
 */

import { COMBAT } from '../core/combatTune';
import type { HullIntegrity, HullZoneId, Racer } from '../core/types';

export const HULL_MAX_HP = COMBAT.hull.maxHp;
export const HULL_ZONES: HullZoneId[] = ['bow', 'mid', 'stern', 'port', 'starboard'];

export function createHull(maxHp: number = HULL_MAX_HP): HullIntegrity {
  return {
    hp: maxHp,
    maxHp,
    trauma: 0,
    hitFlash: 0,
    zones: { bow: 1, mid: 1, stern: 1, port: 1, starboard: 1 },
    lastHitZone: null,
    lastHitFlash: 0,
    steerBias: 0,
    throttleCut: 0,
    boostBleed: 0,
  };
}

export function resetHull(h: HullIntegrity): void {
  h.hp = h.maxHp;
  h.trauma = 0;
  h.hitFlash = 0;
  h.zones.bow = 1;
  h.zones.mid = 1;
  h.zones.stern = 1;
  h.zones.port = 1;
  h.zones.starboard = 1;
  h.lastHitZone = null;
  h.lastHitFlash = 0;
  h.steerBias = 0;
  h.throttleCut = 0;
  h.boostBleed = 0;
}

export function syncHullHp(h: HullIntegrity): void {
  const z = h.zones;
  const mean = (z.bow + z.mid + z.stern + z.port + z.starboard) / 5;
  h.hp = mean * h.maxHp;
}

export type RepairHullOpts = {
  /** 0…1 integrity restored per zone (default 0.35). */
  zoneAmount?: number;
  /** Clear steer bias / throttle cut / boost bleed. */
  clearAilments?: boolean;
  /** Reduce trauma by this amount (default 0.2). */
  traumaRelief?: number;
  /** Only repair these zones; default all. */
  zones?: HullZoneId[];
};

/** Restore zoned hull integrity — health boxes / docks. */
export function repairHull(h: HullIntegrity, opts: RepairHullOpts = {}): void {
  const amount = opts.zoneAmount ?? 0.35;
  const list = opts.zones ?? HULL_ZONES;
  for (const z of list) {
    h.zones[z] = Math.min(1, h.zones[z] + amount);
  }
  syncHullHp(h);
  if (opts.clearAilments !== false) {
    h.steerBias = 0;
    h.throttleCut = 0;
    h.boostBleed = 0;
  }
  if (opts.traumaRelief !== undefined) {
    h.trauma = Math.max(0, h.trauma - opts.traumaRelief);
  } else {
    h.trauma = Math.max(0, h.trauma - 0.2);
  }
  h.hitFlash = 0.15;
  h.lastHitZone = null;
  h.lastHitFlash = 0;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v));
}

/**
 * Throttle authority — zone / trauma based, not HP-linear.
 * At ~30% integrity the craft still has most thrust; limp only when the bow
 * is shredded or temporary cut is active.
 */
export function hullThrottleScale(h: HullIntegrity): number {
  const H = COMBAT.hull;
  const hpFrac = clamp(h.hp / Math.max(1, h.maxHp), 0, 1);
  // Gentle structural wear: 30% HP ≈ ~0.85 authority, not 0.30.
  const structural = H.throttleFloor + (1 - H.throttleFloor) * Math.pow(hpFrac, 0.4);
  const bowMul = 1 - (1 - h.zones.bow) * H.bowThrottleLoss;
  const traumaMul = 1 - h.trauma * H.traumaThrottleLoss;
  const cut = h.throttleCut > 0 ? H.throttleCutMul : 1;
  return clamp(structural * bowMul * traumaMul * cut, H.throttleFloor * 0.85, 1);
}

/** Steering authority / bias from flank damage (still driveable when low). */
export function hullSteerMods(h: HullIntegrity): { scale: number; bias: number } {
  const H = COMBAT.hull;
  const flank = (h.zones.port + h.zones.starboard) * 0.5;
  const scale = H.steerFloor + (1 - H.steerFloor) * flank;
  const asym = (h.zones.starboard - h.zones.port) * H.flankBias;
  return { scale, bias: clamp(h.steerBias + asym, -0.45, 0.45) };
}

/** Boost / afterburner authority from stern integrity. */
export function hullBoostScale(h: HullIntegrity): number {
  const H = COMBAT.hull;
  return clamp(1 - (1 - h.zones.stern) * H.sternBoostLoss, 0.48, 1);
}

/** How many hull zones have dropped below the fail threshold. */
export function failedSystemCount(h: HullIntegrity): number {
  const lim = COMBAT.hull.systemFailAt;
  let n = 0;
  for (const z of HULL_ZONES) if (h.zones[z] <= lim) n++;
  return n;
}

/**
 * Structural / systems wreck check — HP collapse, or too many dead systems,
 * or no remaining control/propulsion combination.
 */
export function shouldWreckHull(h: HullIntegrity): boolean {
  const H = COMBAT.hull;
  if (h.hp <= 0.5) return true;
  if (failedSystemCount(h) >= H.systemsFailToWreck) return true;
  const fail = H.systemFailAt;
  const flanksDead = h.zones.port <= fail && h.zones.starboard <= fail;
  const driveDead = h.zones.bow <= fail && h.zones.stern <= fail;
  // No steering left and the frame or nose is gone.
  if (flanksDead && (h.zones.bow <= fail || h.zones.mid <= fail)) return true;
  // Propulsion and core both gone.
  if (driveDead && h.zones.mid <= fail) return true;
  return false;
}

/**
 * Map a world-space contact normal (from hull toward the other craft) into a
 * local impact zone.
 */
export function zoneFromImpactNormal(heading: number, nx: number, nz: number): HullZoneId {
  const fwdX = Math.sin(heading);
  const fwdZ = Math.cos(heading);
  const rightX = Math.cos(heading);
  const rightZ = -Math.sin(heading);
  const along = nx * fwdX + nz * fwdZ;
  const side = nx * rightX + nz * rightZ;
  if (along > 0.5) return 'bow';
  if (along < -0.5) return 'stern';
  if (Math.abs(side) > Math.abs(along)) return side > 0 ? 'starboard' : 'port';
  return 'mid';
}

export type HullDamageOpts = {
  trauma?: number;
  zone?: HullZoneId;
  effects?: {
    steerBias?: number;
    throttleCut?: number;
    boostBleed?: number;
  };
};

function damageZone(h: HullIntegrity, zone: HullZoneId, frac: number): void {
  h.zones[zone] = Math.max(0, h.zones[zone] - frac);
}

/**
 * Apply structural damage into zones. Syncs `r.state.hp`. Returns true if wrecked.
 */
export function applyHullDamage(
  r: Racer,
  amount: number,
  opts: HullDamageOpts = {},
  raceTime = 0,
): boolean {
  if (amount <= 0 || r.destroyed || r.state.hp <= 0) return false;
  const h = r.hull;
  const zone = opts.zone ?? 'mid';
  const primary = amount * 0.72;
  const splash = amount * 0.28;
  damageZone(h, zone, primary / (h.maxHp / 5));
  damageZone(h, 'mid', splash / (h.maxHp / 5));
  if (zone !== 'mid') {
    if (zone === 'bow' || zone === 'stern') {
      damageZone(h, 'port', (splash * 0.15) / (h.maxHp / 5));
      damageZone(h, 'starboard', (splash * 0.15) / (h.maxHp / 5));
    } else {
      damageZone(h, 'bow', (splash * 0.1) / (h.maxHp / 5));
      damageZone(h, 'stern', (splash * 0.1) / (h.maxHp / 5));
    }
  }

  syncHullHp(h);
  r.state.hp = h.hp;
  r.state.maxHp = h.maxHp;
  if (opts.trauma) h.trauma = Math.min(1, h.trauma + opts.trauma);
  h.hitFlash = Math.max(h.hitFlash, 0.22);
  h.lastHitZone = zone;
  h.lastHitFlash = 0.55;
  r.state.hitFlash = Math.max(r.state.hitFlash, 0.25 + Math.min(0.5, amount / 40));

  if (opts.effects) {
    if (opts.effects.steerBias) {
      h.steerBias = clamp(h.steerBias + opts.effects.steerBias, -0.7, 0.7);
    }
    if (opts.effects.throttleCut) {
      h.throttleCut = Math.max(h.throttleCut, opts.effects.throttleCut);
    }
    if (opts.effects.boostBleed) {
      h.boostBleed = Math.max(h.boostBleed, opts.effects.boostBleed);
      r.state.boostMeter = Math.max(0, r.state.boostMeter - opts.effects.boostBleed);
    }
  }

  if (zone === 'bow') h.trauma = Math.min(1, h.trauma + amount * 0.002);
  if (zone === 'stern') h.trauma = Math.min(1, h.trauma + amount * 0.0015);

  if (shouldWreckHull(h)) {
    wreckRacer(r, raceTime);
    return true;
  }
  return false;
}

/**
 * Collision closing-speed → base damage.
 * `closingSpeed` is signed (negative = approaching). Soft grazes deal nothing;
 * high-speed pack slams scale up hard.
 */
export function collisionHullDamage(closingSpeed: number, relSpeed = 0): number {
  const C = COMBAT.collision;
  const closing = Math.max(0, -closingSpeed);
  if (closing < C.grazeClosing) return 0;
  const t = clamp(closing / C.closingNorm, 0, 1);
  const base = t * t * C.damageQuad + t * C.damageLin;
  const rel = clamp(relSpeed / C.relSpeedNorm, 0, 1);
  return base * (C.damageRelBase + rel * C.damageRelGain);
}

/** 0…1 impact severity from closing speed (for HUD / shake). */
export function collisionImpactStrength(closingSpeed: number): number {
  const C = COMBAT.collision;
  return clamp((-closingSpeed - C.strengthOffset) / C.strengthSpan, 0, 1);
}

export function impactLabel(strength: number): 'GRAZE' | 'HIT' | 'HEAVY' | 'CRUSH' {
  const C = COMBAT.collision;
  if (strength < C.labelGraze) return 'GRAZE';
  if (strength < C.labelHit) return 'HIT';
  if (strength < C.labelHeavy) return 'HEAVY';
  return 'CRUSH';
}

/** Wreck a craft — DNF (not a finish), freeze motion, tilt the hull. */
export function wreckRacer(r: Racer, raceTime = 0): void {
  if (r.destroyed) return;
  r.destroyed = true;
  // Exploded ≠ finished — keep them out of the classement / finish order.
  r.finished = false;
  r.finishTime = raceTime;
  r.place = Number.MAX_SAFE_INTEGER;
  r.wrongWay = false;
  const h = r.hull;
  h.hp = 0;
  r.state.hp = 0;
  for (const z of HULL_ZONES) h.zones[z] = 0;
  h.hitFlash = 0.55;
  h.lastHitFlash = 0.8;
  r.state.hitFlash = 0.7;
  r.state.velocity.set(0, 0, 0);
  r.state.forwardSpeed = 0;
  r.state.boosting = false;
  r.state.boostMeter = 0;
  r.state.nitroTime = 0;
  r.state.weapon = 'none';
  r.state.weaponAmmo = 0;
  r.state.appliedThrottle = 0;
  r.state.pitch = 0.35;
  r.state.roll = r.id % 2 === 0 ? 0.55 : -0.55;
  r.controls.throttle = 0;
  r.controls.brake = 0;
  r.controls.steer = 0;
  r.controls.boost = false;
  r.controls.airbrakeL = false;
  r.controls.airbrakeR = false;
  r.controls.firePressed = false;
  // Hide hull — ShipExplosionFx plays the wreck blast at this pose.
  r.root.visible = false;
}

export function collisionImpactEffects(zone: HullZoneId, closing: number): {
  damageMul: number;
  spinMul: number;
  steerBias?: number;
  throttleCut?: number;
  boostBleed?: number;
} {
  const C = COMBAT.collision;
  const strength = Math.min(1, Math.max(0, -closing / C.zoneClosingNorm));
  const Z = C.zone;
  switch (zone) {
    case 'bow':
      return {
        damageMul: Z.bow.damageMul,
        spinMul: Z.bow.spinMul,
        throttleCut: Z.bow.throttleCutBase + strength * Z.bow.throttleCutGain,
      };
    case 'stern':
      return {
        damageMul: Z.stern.damageMul,
        spinMul: Z.stern.spinMul,
        boostBleed: Z.stern.boostBleedBase + strength * Z.stern.boostBleedGain,
      };
    case 'port':
      return {
        damageMul: Z.port.damageMul,
        spinMul: Z.port.spinMul,
        steerBias: -1 * (Z.port.steerBiasBase + strength * Z.port.steerBiasGain),
        throttleCut: Z.port.throttleCutGain * strength,
      };
    case 'starboard':
      return {
        damageMul: Z.starboard.damageMul,
        spinMul: Z.starboard.spinMul,
        steerBias: 1 * (Z.starboard.steerBiasBase + strength * Z.starboard.steerBiasGain),
        throttleCut: Z.starboard.throttleCutGain * strength,
      };
    default:
      return {
        damageMul: Z.mid.damageMul,
        spinMul: Z.mid.spinMul,
        throttleCut: Z.mid.throttleCutGain * strength,
      };
  }
}

/** Per-frame decay of temporary collision ailments. */
export function tickHullEffects(h: HullIntegrity, dt: number): void {
  h.lastHitFlash = Math.max(0, h.lastHitFlash - dt);
  h.hitFlash = Math.max(0, h.hitFlash - dt);
  h.throttleCut = Math.max(0, h.throttleCut - dt);
  h.boostBleed = Math.max(0, h.boostBleed - dt * 0.5);
  h.steerBias *= Math.exp(-2.4 * dt);
  if (Math.abs(h.steerBias) < 0.01) h.steerBias = 0;
}

/** Keep ShipState.hp aligned after external hp writes (e.g. old rocket path). */
export function syncStateFromHull(r: Racer): void {
  r.state.hp = r.hull.hp;
  r.state.maxHp = r.hull.maxHp;
}
